import json, os, sys, time, base64, mimetypes, urllib.request, urllib.error

API_KEY = os.environ.get("VAR_FAL_API_KEY") or os.environ.get("VAR_FAL_KEY") or ""
WORK_DIR = os.environ.get("AT_WORK_DIR") or "/tmp"
ASSETS_DIR = os.environ.get("AT_ASSETS_DIR") or os.path.join(WORK_DIR, "assets")
AVATAR_DIR = os.path.join(ASSETS_DIR, "avatars")

def die(msg, **extra):
    out = {"error": msg}
    out.update(extra)
    print(json.dumps(out)); sys.exit(0)

if not API_KEY:
    die("FAL API key not configured (set fal_api_key or FAL_KEY)")

def http_json(url, payload=None, method=None, timeout=60):
    data = json.dumps(payload).encode() if payload is not None else None
    req = urllib.request.Request(url, data=data, method=method or ("POST" if data else "GET"),
        headers={"Authorization": "Key " + API_KEY, "Content-Type": "application/json"})
    with urllib.request.urlopen(req, timeout=timeout) as r:
        return json.load(r)

def resolve_avatar(ref):
    """Resolve an avatar reference: URL, local path, or library name."""
    if not ref:
        return ref
    if ref.startswith(("http://", "https://", "data:")):
        return ref
    if os.path.isfile(os.path.expanduser(ref)):
        return os.path.expanduser(ref)
    # Library lookup by name/slug: avatars/<slug>.{png,jpg,jpeg,webp}
    slug = ref.strip().lower().replace(" ", "-")
    for ext in ("png", "jpg", "jpeg", "webp"):
        p = os.path.join(AVATAR_DIR, slug + "." + ext)
        if os.path.isfile(p):
            return p
    manifest = os.path.join(AVATAR_DIR, slug + ".json")
    if os.path.isfile(manifest):
        try:
            m = json.load(open(manifest))
            if m.get("file") and os.path.isfile(m["file"]):
                return m["file"]
        except Exception:
            pass
    die("avatar not found: %r (not a URL, file, or library name; use list_avatars)" % ref)

def to_fal_url(path_or_url):
    """Return a URL FAL can fetch: pass URLs through, upload local files to
    the FAL CDN, fall back to a base64 data URI."""
    if path_or_url.startswith(("http://", "https://", "data:")):
        return path_or_url
    p = os.path.expanduser(path_or_url)
    if not os.path.isfile(p):
        die("file not found: " + p)
    ctype = mimetypes.guess_type(p)[0] or "application/octet-stream"
    blob = open(p, "rb").read()
    try:
        init = http_json("https://rest.alpha.fal.ai/storage/upload/initiate?storage_type=fal-cdn-v3",
                         {"content_type": ctype, "file_name": os.path.basename(p)}, timeout=30)
        up = urllib.request.Request(init["upload_url"], data=blob,
                                    headers={"Content-Type": ctype}, method="PUT")
        with urllib.request.urlopen(up, timeout=600):
            pass
        return init["file_url"]
    except Exception:
        if len(blob) > 20 * 1024 * 1024:
            die("CDN upload failed and file too large (>20MB) for inline data URI: " + p)
        return "data:" + ctype + ";base64," + base64.b64encode(blob).decode()

def queue_run(model, payload, poll_minutes=25):
    """Submit to queue.fal.run and poll until completion."""
    sub = http_json("https://queue.fal.run/" + model, payload, timeout=60)
    req_id = sub.get("request_id")
    if not req_id:
        die("FAL submit failed", raw=str(sub)[:800])
    status_url = sub.get("status_url") or "https://queue.fal.run/%s/requests/%s/status" % (model, req_id)
    resp_url = sub.get("response_url") or "https://queue.fal.run/%s/requests/%s" % (model, req_id)
    deadline = time.time() + poll_minutes * 60
    while time.time() < deadline:
        time.sleep(10)
        try:
            st = http_json(status_url, timeout=30)
        except Exception:
            continue
        status = st.get("status", "")
        if status == "COMPLETED":
            return http_json(resp_url, timeout=60), req_id
        if status in ("FAILED", "ERROR"):
            die("FAL job failed", status=status, request_id=req_id)
    die("FAL job timed out", request_id=req_id, status_url=status_url, response_url=resp_url,
        hint="Retry, or poll the status_url manually with the API key.")

def download(url, out_path):
    req = urllib.request.Request(url)
    with urllib.request.urlopen(req, timeout=600) as r, open(out_path, "wb") as f:
        while True:
            chunk = r.read(1 << 20)
            if not chunk:
                break
            f.write(chunk)
    return os.path.getsize(out_path)

def save_to_library(src_path, name, description="", source_url=""):
    os.makedirs(AVATAR_DIR, exist_ok=True)
    slug = name.strip().lower().replace(" ", "-")
    ext = os.path.splitext(src_path)[1].lstrip(".") or "png"
    dest = os.path.join(AVATAR_DIR, slug + "." + ext)
    if os.path.abspath(src_path) != os.path.abspath(dest):
        import shutil
        shutil.copyfile(src_path, dest)
    now = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())
    mpath = os.path.join(AVATAR_DIR, slug + ".json")
    manifest = {}
    if os.path.isfile(mpath):
        try:
            manifest = json.load(open(mpath))
        except Exception:
            manifest = {}
    manifest.update({"name": name, "slug": slug, "file": dest, "version": 2, "updated_at": now})
    if description:
        manifest["description"] = description
    manifest.setdefault("description", "")
    if source_url:
        manifest["source_url"] = source_url
    manifest.setdefault("source_url", "")
    manifest.setdefault("created_at", now)
    refs = [r for r in (manifest.get("reference_images") or [])]
    base = os.path.basename(dest)
    if base not in refs and dest not in refs:
        refs.insert(0, base)
    manifest["reference_images"] = refs
    write_manifest(mpath, manifest)
    return manifest

def uid():
    import uuid
    return uuid.uuid4().hex[:10]

def slugify(name):
    return name.strip().lower().replace(" ", "-")

def manifest_path(slug):
    return os.path.join(AVATAR_DIR, slug + ".json")

def load_manifest(ref):
    """Load a library character by name/slug. Returns (slug, manifest) or dies."""
    slug = slugify(ref)
    p = manifest_path(slug)
    if os.path.isfile(p):
        try:
            return slug, json.load(open(p))
        except Exception as e:
            die("corrupt manifest for %r: %s" % (ref, e))
    for ext in ("png", "jpg", "jpeg", "webp"):
        img = os.path.join(AVATAR_DIR, slug + "." + ext)
        if os.path.isfile(img):
            return slug, {"name": ref, "slug": slug, "file": img}
    avail = sorted(os.path.splitext(f)[0] for f in os.listdir(AVATAR_DIR) if f.endswith(".json")) if os.path.isdir(AVATAR_DIR) else []
    die("character not found in library: %r" % ref, available=avail)

def write_manifest(path, manifest):
    """Atomic manifest write: temp file + rename."""
    os.makedirs(os.path.dirname(path), exist_ok=True)
    tmp = path + ".tmp-" + uid()
    with open(tmp, "w") as f:
        json.dump(manifest, f, indent=1)
    os.replace(tmp, path)

# ---- cinema helpers -------------------------------------------------------
# Model IDs are kept here in one place because the fal catalog moves fast.
# Verify any of them at https://fal.ai/models/<model-id>/llms.txt
MODEL_KLING_I2V = "fal-ai/kling-video/v3/pro/image-to-video"
MODEL_VEO_REF = "fal-ai/veo3.1/reference-to-video"
MODEL_SEEDANCE_REF = "bytedance/seedance-2.5/reference-to-video"
MODEL_VIDU_REF = "fal-ai/vidu/q2/reference-to-video"
MODEL_VEO_FLF = "fal-ai/veo3.1/first-last-frame-to-video"
MODEL_MINIMAX_I2V = "minimax/h3-max/image-to-video"
MODEL_PIXVERSE_TRANSITION = "fal-ai/pixverse/v6/transition"
MODEL_SORA_I2V = "fal-ai/sora-2/image-to-video"
MODEL_SORA_T2V = "fal-ai/sora-2/text-to-video"
MODEL_SORA_CHARACTERS = "fal-ai/sora-2/characters"

def arg(name, default=""):
    return os.environ.get("ARG_" + name, "") or default

def arg_list(name):
    raw = os.environ.get("ARG_" + name, "")
    if not raw:
        return []
    try:
        v = json.loads(raw)
        if isinstance(v, list):
            return [str(x) for x in v if str(x).strip()]
    except ValueError:
        pass
    return [x.strip() for x in raw.split(",") if x.strip()]

def arg_int(name, default=None):
    raw = os.environ.get("ARG_" + name, "")
    if not raw:
        return default
    try:
        return int(float(raw))
    except ValueError:
        die(name.lower() + " must be a number, got %r" % raw)

def arg_bool(name, default=True):
    raw = os.environ.get("ARG_" + name, "").strip().lower()
    if not raw:
        return default
    return raw not in ("false", "0", "no", "off")

def character_files(name):
    """Library character -> (slug, manifest, [local reference image paths])."""
    slug, manifest = load_manifest(name)
    files = []
    for r in manifest.get("reference_images") or []:
        p = r if os.path.isabs(r) else os.path.join(AVATAR_DIR, r)
        if os.path.isfile(p) and p not in files:
            files.append(p)
    f = manifest.get("file")
    if not files and f and os.path.isfile(f):
        files = [f]
    if not files:
        die("character %r has no reference images on disk; run create_avatar (save_as=...) and character_sheet first" % name)
    return slug, manifest, files

def resolve_image(ref):
    """Image reference -> FAL-fetchable URL. Accepts URL, local path, or library character name (portrait)."""
    if not ref:
        return ""
    if ref.startswith(("http://", "https://", "data:")):
        return ref
    p = os.path.expanduser(ref)
    if os.path.isfile(p):
        return to_fal_url(p)
    return to_fal_url(resolve_avatar(ref))

def with_style(prompt, style):
    style = (style or "").strip()
    return (prompt.rstrip() + " Visual style: " + style) if style else prompt

def bible_notes(manifests):
    """Wardrobe/style notes from character manifests, to fold into the prompt."""
    notes = []
    for m in manifests:
        bits = [(m.get(k) or "").strip() for k in ("wardrobe", "style_notes")]
        bits = [b for b in bits if b]
        if bits:
            notes.append("%s: %s" % (m.get("name") or m.get("slug"), "; ".join(bits)))
    return ("Character consistency - " + " | ".join(notes)) if notes else ""

def save_video(res, prefix):
    vid = res.get("video") or {}
    url = vid.get("url") or ""
    if not url:
        die("FAL returned no video", raw=str(res)[:800])
    os.makedirs(WORK_DIR, exist_ok=True)
    out = os.path.join(WORK_DIR, "%s-%s.mp4" % (prefix, uid()))
    size = download(url, out)
    return {"video_file": out, "video_url": url, "size_bytes": size}

prompt = arg("PROMPT")
if not prompt:
    die("prompt is required")
urls, cast, manifests = [], [], []
for c in arg_list("CHARACTERS"):
    slug, m, files = character_files(c)
    image_tags = []
    for p in files[:3]:
        u = to_fal_url(p)
        if u not in urls:
            urls.append(u)
        image_tags.append("@Image%d" % (urls.index(u) + 1))
    cast.append({"character": slug, "images": image_tags})
    manifests.append(m)
for r in arg_list("EXTRA_REFERENCE_IMAGES"):
    u = resolve_image(r)
    if u and u not in urls:
        urls.append(u)
if len(urls) > 30:
    urls = urls[:30]

duration = arg("DURATION", "auto")
if duration != "auto":
    d = arg_int("DURATION")
    if not 4 <= d <= 30:
        die("duration must be 4-30 seconds or auto")
    duration = str(d)
resolution = arg("RESOLUTION", "720p")
if resolution not in ("480p", "720p", "1080p"):
    die("resolution must be 480p, 720p or 1080p")
ar = arg("ASPECT_RATIO", "auto")
if ar not in ("auto", "21:9", "16:9", "4:3", "1:1", "3:4", "9:16"):
    die("aspect_ratio must be auto, 21:9, 16:9, 4:3, 1:1, 3:4 or 9:16")

full_prompt = with_style(prompt, arg("STYLE"))
notes = bible_notes(manifests)
if notes:
    full_prompt += " " + notes
payload = {"prompt": full_prompt, "resolution": resolution, "duration": duration,
           "aspect_ratio": ar, "generate_audio": arg_bool("AUDIO", True)}
if urls:
    payload["image_urls"] = urls
audio_refs = [resolve_image(a) if not a.startswith("http") else a for a in arg_list("AUDIO_REFERENCES")]
if audio_refs:
    payload["audio_urls"] = audio_refs

res, req_id = queue_run(MODEL_SEEDANCE_REF, payload, poll_minutes=40)
out = save_video(res, "scene-long")
out.update({"model": MODEL_SEEDANCE_REF, "request_id": req_id, "characters": cast,
            "seed": res.get("seed"), "reference_count": len(urls)})
print(json.dumps(out))

